create or replace function public.is_qualifying_return_visit(p_user_id uuid,p_location_id uuid,p_check_in_at timestamptz default now(),p_check_in_id uuid default null) returns boolean language plpgsql security definer set search_path='public','auth','extensions','pg_temp' as $function$ declare v_last_check timestamptz; v_today integer; v_cap integer:=5; begin if p_user_id is null or p_location_id is null then return false; end if; select max(checked_in_at) into v_last_check from public.check_ins where user_id=p_user_id and location_id=p_location_id and checked_in_at < p_check_in_at and (p_check_in_id is null or id<>p_check_in_id); if v_last_check is not null and p_check_in_at-v_last_check < interval '60 minutes' then return false; end if; select count(*)::integer into v_today from public.point_transactions where user_id=p_user_id and reason='check_in' and created_at >= date_trunc('day',p_check_in_at) and created_at < date_trunc('day',p_check_in_at)+interval '1 day'; return v_today < v_cap; end; $function$;

create or replace function public.gamification_activity_trigger() returns trigger language plpgsql security definer set search_path='public','auth','extensions','pg_temp' as $function$ declare v_eligible boolean:=true; begin if auth.uid() is null then return new; end if; if new.user_id is distinct from auth.uid() then return new; end if; if TG_TABLE_NAME='check_ins' then v_eligible:=public.is_qualifying_return_visit(new.user_id,new.location_id,new.checked_in_at,new.id); if v_eligible then perform public.record_gamification_activity('check_in',new.id); if not exists(select 1 from public.check_ins where user_id=new.user_id and location_id=new.location_id and id<>new.id) then perform public.record_gamification_activity('location_diversity',new.location_id); end if; end if; elsif TG_TABLE_NAME='location_bathroom_verifications' then perform public.record_gamification_activity('verification',new.id); elsif TG_TABLE_NAME='reviews' then if new.status='published' then perform public.record_gamification_activity('review',new.id); end if; elsif TG_TABLE_NAME='favorites' then perform public.record_gamification_activity('favorite',new.location_id); elsif TG_TABLE_NAME='social_posts' then if coalesce(new.status,'published')='published' then perform public.record_gamification_activity('social_post',new.id); end if; elsif TG_TABLE_NAME='contest_entries' then perform public.record_gamification_activity('contest_entry',new.contest_id); elsif TG_TABLE_NAME='route_events' then if new.event_type='route_completed' then perform public.record_gamification_activity('route_completed',new.route_id); elsif new.event_type='stop_completed' then perform public.record_gamification_activity('route_stop_completed',new.route_stop_id); elsif new.event_type='route_shared' then perform public.record_gamification_activity('share',new.route_id); end if; elsif TG_TABLE_NAME='analytics_events' then if new.event_type='qr_scan' then perform public.record_gamification_activity('qr_scan',new.id); elsif new.event_type='event_rsvp' then perform public.record_gamification_activity('event_rsvp',new.event_id); elsif new.event_type='share' then perform public.record_gamification_activity('share',new.id); end if; end if; return new; exception when others then raise warning 'gamification trigger skipped: %',sqlerrm; return new; end; $function$;

create or replace function public.trg_quest_checkin_activity() returns trigger language plpgsql security definer set search_path='public','auth','extensions','pg_temp' as $function$ begin if public.is_qualifying_return_visit(new.user_id,new.location_id,new.checked_in_at,new.id) then perform public.quest_advance_activity(new.user_id,'checkin',new.id,new.location_id,new.id,new.qr_code_id,jsonb_build_object('verification_method',new.verification_method,'progression_eligible',true)); end if; return new; end; $function$;
